installer-gui-script.script:
function checkMacOS() {
    if (system.compareVersions(system.version.ProductVersion, '@MIN_MACOS@') < 0) {
        my.result.title = 'StudioRider needs macOS 13 or later';
        my.result.message = 'StudioRider sends what your DAW plays to listeners through a Cloudflare link, '
            + 'and Cloudflare\'s program (cloudflared) only runs on macOS 13 Ventura or later. '
            + 'This Mac has macOS ' + system.version.ProductVersion + '.';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
